import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useHistory } from "react-router-dom";
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { ContactShadows, Html } from "@react-three/drei";
import { AGENTS } from "./LilAgents";
import "./LilAgents3D.css";

// WebGL variant of the hero companions — same two bots, same names, phrases
// and terminal copy as the CSS/SVG original, rebuilt as real geometry so they
// get perspective, a grounded contact shadow, coloured light spill off their
// own hue, and heads that track the pointer. Opt-in via ?agents=3d; the
// original stays the default and is untouched.

const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

// ---------------------------------------------------------------------------
// Choreography — ported from lil-agents' WalkerCharacter (MIT). Instead of one
// fixed loop, each bot independently picks a short walk, then rests, with the
// direction biased away from whichever edge it's near.
// ---------------------------------------------------------------------------
const BOT_SCALE = 0.9;
// Distance from the bot's origin down to the soles, so the root can be lifted
// by it and the whole scene share a ground plane at y = 0.
const FOOT = 0.44 * BOT_SCALE;

const TRACK = 4.2; // half-width of the strip the bots roam, in world units
// ~0.45 body-heights per second. At the old 1.05 the bots covered a full
// body-height each second and the stride had to cycle ~5.8 steps/s to keep the
// feet from scrubbing, which read as buzzing legs rather than a walk.
const SPEED = 0.5; // world units per second at full walk
const MIN_SEP = 0.2; // closest the two may stand, in track fraction — a bot
// is ~1.3 world units wide, so anything less overlaps them
const STRIDE = 0.42; // world units per full leg cycle -> ~2.4 steps/s
const PAUSE = [4.5, 11]; // seconds of rest between walks
const WALK_SPAN = [0.16, 0.4]; // fraction of the track covered per walk

// Fractions of a walk spent accelerating / decelerating. lil-agents derives
// these by hand from its video's frames; here the gait is procedural, so the
// profile can just be declared.
const ACCEL = 0.2;
const DECEL = 0.2;

const clamp01 = (v) => Math.min(Math.max(v, 0), 1);
const lerp = (a, b, t) => a + (b - a) * t;

// Integral of a trapezoidal velocity profile, normalised so t=1 -> distance 1.
// Driving position from this (rather than a generic ease) is what makes the
// start and stop read as a body with weight.
const travelEase = (t) => {
  const dLin = 1 - ACCEL - DECEL;
  const v = 1 / (ACCEL / 2 + dLin + DECEL / 2);
  if (t <= ACCEL) return (v * t * t) / (2 * ACCEL);
  if (t <= ACCEL + dLin) return (v * ACCEL) / 2 + v * (t - ACCEL);
  const tt = t - ACCEL - dLin;
  return (v * ACCEL) / 2 + v * dLin + v * (tt - (tt * tt) / (2 * DECEL));
};

const posToX = (pos) => (pos - 0.5) * 2 * TRACK;

function restAfterWalk(self, now) {
  self.walking = false;
  self.pauseUntil = now + lerp(PAUSE[0], PAUSE[1], Math.random());
}

// Pick the next walk: turn away from a nearby edge, otherwise choose at random,
// and never plan to stop within MIN_SEP of the other bot.
function planWalk(self, peers, now) {
  if (self.pos > 0.85) self.dir = -1;
  else if (self.pos < 0.15) self.dir = 1;
  else self.dir = Math.random() < 0.5 ? -1 : 1;

  const span = lerp(WALK_SPAN[0], WALK_SPAN[1], Math.random());
  let to = clamp01(self.pos + self.dir * span);

  // Clamp against the peer's *side*, not just the final gap — checking only
  // the destination (as the original does) still lets one walk straight
  // through the other on the way there.
  for (const other of peers) {
    if (other === self) continue;
    if (self.dir > 0 && other.pos > self.pos) {
      to = Math.min(to, other.pos - MIN_SEP);
    } else if (self.dir < 0 && other.pos < self.pos) {
      to = Math.max(to, other.pos + MIN_SEP);
    }
  }
  to = clamp01(to);

  // Boxed in — wait rather than jitter on the spot
  if (Math.abs(to - self.pos) < 0.03) {
    restAfterWalk(self, now);
    return;
  }

  self.from = self.pos;
  self.to = to;
  // Constant ground speed, so a longer walk simply takes longer
  self.duration = Math.max(
    0.8,
    (Math.abs(to - self.pos) * TRACK * 2) / SPEED
  );
  self.startedAt = now;
  self.walking = true;
  self.travelled = 0; // every walk starts on the same foot
  if (to !== self.pos) self.facing = to > self.pos ? 1 : -1;
}

// ---------------------------------------------------------------------------
// One bot, built from rounded primitives
// ---------------------------------------------------------------------------
function Bot({
  agent,
  side,
  phase,
  frozen,
  onSelect,
  isOpen,
  bubbleText,
  portal,
  onNavigate,
  walkState,
  peers,
}) {
  const root = useRef();
  const body = useRef();
  const head = useRef();
  const armL = useRef();
  const armR = useRef();
  const legL = useRef();
  const legR = useRef();
  const eyes = useRef();
  const tip = useRef();
  const [hovered, setHovered] = useState(false);

  useFrame((state, delta) => {
    if (!root.current) return;
    const time = state.clock.getElapsedTime();
    const st = walkState;

    if (frozen) {
      root.current.position.set(posToX(st.pos), FOOT, 0);
      return;
    }

    // --- Walk / rest state machine -----------------------------------------
    // Frozen in place while its terminal is open, like the original does.
    if (isOpen) {
      if (st.walking) restAfterWalk(st, time);
      st.pauseUntil = time + 1.5;
    } else if (st.walking) {
      const t = clamp01((time - st.startedAt) / st.duration);
      st.pos = lerp(st.from, st.to, travelEase(t));
      if (t >= 1) restAfterWalk(st, time);
    } else if (time >= st.pauseUntil) {
      planWalk(st, peers, time);
    }

    const x = posToX(st.pos);
    // Clamp dt: a backgrounded tab returns one enormous frame, which would
    // otherwise spike the speed and teleport the stride phase.
    const dt = Math.min(delta, 0.05);
    const moved = Math.abs(x - root.current.position.x);
    const groundSpeed = dt > 0 ? moved / dt : 0;
    // Distance travelled drives the stride phase, so the feet can never scrub.
    st.travelled += moved;
    root.current.position.x = x;

    // Swing amplitude ramps with ground speed rather than switching on at a
    // threshold. Gating on a boolean snapped the legs between a full stride
    // and dead-straight every time the trapezoid's accel/decel crossed the
    // cutoff — which is what made the gait look inconsistent.
    const targetGait = st.walking
      ? Math.min(groundSpeed / (SPEED * 0.35), 1)
      : 0;
    st.gait = lerp(st.gait, targetGait, 0.12);
    const amp = st.gait;

    const stridePhase = (st.travelled / STRIDE) * Math.PI * 2;
    const swing = Math.sin(stridePhase) * amp;
    const walking = amp > 0.06;

    // Lift on each step, fading with the same amplitude
    root.current.position.y =
      FOOT + Math.abs(Math.sin(stridePhase)) * 0.05 * amp;

    // Angle into the direction of travel. A full flip would hide the face, so
    // this is a quarter turn rather than the original's mirrored sprite.
    // Keyed off st.walking, not the amplitude, so the turn holds through the
    // slow parts of the walk instead of unwinding and snapping back.
    root.current.rotation.y = lerp(
      root.current.rotation.y,
      st.walking ? st.facing * 0.34 : 0,
      0.08
    );

    // Two bots standing close and idle acknowledge each other
    const nearPeer = peers.some(
      (o) => o !== st && !o.walking && Math.abs(o.pos - st.pos) < 0.26
    );
    const greeting = !walking && nearPeer;

    if (legL.current) legL.current.rotation.x = swing * 0.55;
    if (legR.current) legR.current.rotation.x = -swing * 0.55;
    if (armL.current) armL.current.rotation.x = -swing * 0.5;

    if (armR.current) {
      if (greeting) {
        armR.current.rotation.x = 0;
        armR.current.rotation.z = lerp(
          armR.current.rotation.z,
          -1.3 + Math.sin(time * 8) * 0.28,
          0.2
        );
      } else {
        armR.current.rotation.z = lerp(armR.current.rotation.z, 0, 0.15);
        armR.current.rotation.x = swing * 0.5;
      }
    }

    // Breathe when standing still
    if (body.current) {
      body.current.position.y = Math.sin(time * 2) * 0.025 * (1 - amp);
      body.current.rotation.z = lerp(
        body.current.rotation.z,
        -st.facing * 0.07 * amp,
        0.12
      );
    }

    // Head follows the pointer when idle, looks ahead when walking
    if (head.current) {
      const target = walking
        ? st.facing * 0.3
        : greeting
        ? (peers.find((o) => o !== st)?.pos ?? st.pos) > st.pos
          ? 0.5
          : -0.5
        : state.mouse.x * 0.5;
      head.current.rotation.y = lerp(head.current.rotation.y, target, 0.07);
      head.current.rotation.x = lerp(
        head.current.rotation.x,
        walking ? 0.05 : -state.mouse.y * 0.18,
        0.07
      );
    }

    // Blink — a quick squash roughly every 3.6s, offset per bot
    if (eyes.current) {
      const b = (time + phase * 7) % 3.6;
      eyes.current.scale.y = b < 0.13 ? 0.1 : 1;
      eyes.current.position.y = b < 0.13 ? 0.26 : 0;
    }

    if (tip.current) {
      const s2 = 1 + Math.sin(time * 3.2 + phase * 6) * 0.18;
      tip.current.scale.setScalar(s2);
    }
  });

  // Candy finish, borrowed from GitHub's WebGL section heads: a glossy
  // clearcoat over a low-roughness base, plus a little emissive in the bot's
  // own hue so the shadow side never goes muddy — a cheap stand-in for the
  // subsurface glow that makes those read as jelly rather than plastic.
  const skin = useMemo(
    () => ({
      color: agent.mid,
      roughness: 0.26,
      metalness: 0,
      clearcoat: 1,
      clearcoatRoughness: 0.32,
      emissive: agent.deep,
      emissiveIntensity: 0.12,
    }),
    [agent.mid, agent.deep]
  );

  return (
    <group
      ref={root}
      position={[posToX(walkState.pos), FOOT, 0]}
      scale={BOT_SCALE}
      onClick={(e) => {
        e.stopPropagation();
        onSelect(agent.id);
      }}
      onPointerOver={() => setHovered(true)}
      onPointerOut={() => setHovered(false)}
    >
      <group ref={body} scale={hovered ? 1.07 : 1}>
        {/* Torso — deliberately small. Cuteness lives in the head-to-body
            ratio, so this stays under half the head's width. */}
        <mesh position={[0, 0.04, 0]} scale={[1, 0.92, 0.88]}>
          <sphereGeometry args={[0.31, 28, 28]} />
          <meshPhysicalMaterial {...skin} />
        </mesh>

        {/* Chest light */}
        <mesh position={[0, 0.04, 0.28]}>
          <circleGeometry args={[0.05, 24]} />
          <meshStandardMaterial
            color={agent.eye}
            emissive={agent.eye}
            emissiveIntensity={0.8}
            toneMapped={false}
          />
        </mesh>

        {/* Stubby arms — little mitts, no elbows */}
        <group ref={armL} position={[-0.36, 0.12, 0.04]}>
          <mesh position={[0, -0.13, 0]} scale={[0.82, 1.25, 0.82]}>
            <sphereGeometry args={[0.12, 20, 20]} />
            <meshPhysicalMaterial
              color={agent.light}
              roughness={0.3}
              clearcoat={1}
              clearcoatRoughness={0.35}
            />
          </mesh>
        </group>
        <group ref={armR} position={[0.36, 0.12, 0.04]}>
          <mesh position={[0, -0.13, 0]} scale={[0.82, 1.25, 0.82]}>
            <sphereGeometry args={[0.12, 20, 20]} />
            <meshPhysicalMaterial
              color={agent.light}
              roughness={0.3}
              clearcoat={1}
              clearcoatRoughness={0.35}
            />
          </mesh>
        </group>

        {/* Short legs, wide stance */}
        <group ref={legL} position={[-0.15, -0.2, 0]}>
          <mesh position={[0, -0.11, 0]} scale={[0.85, 1.15, 0.85]}>
            <sphereGeometry args={[0.11, 18, 18]} />
            <meshPhysicalMaterial
              color={agent.deep}
              roughness={0.32}
              clearcoat={1}
              clearcoatRoughness={0.38}
            />
          </mesh>
        </group>
        <group ref={legR} position={[0.15, -0.2, 0]}>
          <mesh position={[0, -0.11, 0]} scale={[0.85, 1.15, 0.85]}>
            <sphereGeometry args={[0.11, 18, 18]} />
            <meshPhysicalMaterial
              color={agent.deep}
              roughness={0.32}
              clearcoat={1}
              clearcoatRoughness={0.38}
            />
          </mesh>
        </group>

        {/* Head — one continuous rounded form rather than a cluster of
            spheres. The old five-blob build read as a head with two enormous
            ears, and being many meshes it also caught a separate specular on
            each one instead of a single sweep. */}
        {/* Scaled as a whole so ears, eyes, muzzle and antenna keep their
            relative proportions — head-to-torso lands ~1.6x rather than 1.9x */}
        <group ref={head} position={[0, 0.34, 0]} scale={0.85}>
          {/* A high-segment ellipsoid, not a RoundedBox: even at near-max
              radius the box keeps a small flat on each face, and the clearcoat
              glares off it as a hard rectangular streak. */}
          <mesh position={[0, 0.28, 0]} scale={[0.575, 0.5, 0.45]}>
            <sphereGeometry args={[1, 48, 36]} />
            <meshPhysicalMaterial {...skin} />
          </mesh>

          {/* Small ears, tilted out from the top corners */}
          {[-1, 1].map((s) => (
            <mesh
              key={`ear${s}`}
              position={[s * 0.37, 0.76, -0.02]}
              rotation={[0, 0, s * -0.3]}
              scale={[1, 1, 0.55]}
            >
              <coneGeometry args={[0.16, 0.3, 18]} />
              <meshPhysicalMaterial {...skin} />
            </mesh>
          ))}

          {/* Pale muzzle plate across the lower face — the reference's cheeks
              and snout read as one lighter region, and it's what gives the
              face a centre of gravity. */}
          <mesh position={[0, 0.15, 0.33]} scale={[1, 0.78, 0.22]}>
            <sphereGeometry args={[0.3, 30, 30]} />
            <meshPhysicalMaterial
              color={agent.light}
              roughness={0.34}
              clearcoat={1}
              clearcoatRoughness={0.34}
            />
          </mesh>

          {/* Big glossy oval eyes, sat on the muzzle's upper edge */}
          <group ref={eyes} position={[0, 0, 0]}>
            {[-1, 1].map((s) => (
              <group key={s}>
                <mesh position={[s * 0.185, 0.3, 0.37]} scale={[1, 1.14, 0.3]}>
                  <sphereGeometry args={[0.125, 22, 22]} />
                  <meshStandardMaterial color="#ffffff" roughness={0.5} />
                </mesh>
                <mesh position={[s * 0.185, 0.3, 0.395]} scale={[1, 1.15, 0.42]}>
                  <sphereGeometry args={[0.095, 24, 24]} />
                  <meshStandardMaterial
                    color="#16162b"
                    roughness={0.14}
                    metalness={0.1}
                  />
                </mesh>
                {/* Catchlight */}
                <mesh position={[s * 0.21, 0.35, 0.435]}>
                  <sphereGeometry args={[0.026, 14, 14]} />
                  <meshStandardMaterial
                    color="#ffffff"
                    emissive="#ffffff"
                    emissiveIntensity={1.4}
                    toneMapped={false}
                  />
                </mesh>
              </group>
            ))}
          </group>

          {/* Nose */}
          <mesh position={[0, 0.16, 0.45]} scale={[1, 0.7, 0.5]}>
            <sphereGeometry args={[0.042, 14, 14]} />
            <meshStandardMaterial color="#16162b" roughness={0.3} />
          </mesh>

          {/* Little smile */}
          <mesh position={[0, 0.05, 0.44]} rotation={[0, 0, Math.PI]}>
            <torusGeometry args={[0.07, 0.012, 10, 20, Math.PI * 0.8]} />
            <meshStandardMaterial color="#16162b" roughness={0.4} />
          </mesh>

          {/* Blush */}
          {[-1, 1].map((s) => (
            <mesh
              key={`b${s}`}
              position={[s * 0.4, 0.13, 0.3]}
              scale={[1, 0.7, 0.22]}
            >
              <sphereGeometry args={[0.1, 18, 18]} />
              <meshBasicMaterial
                color={agent.light}
                transparent
                opacity={0.55}
                toneMapped={false}
              />
            </mesh>
          ))}

          {/* Antenna, set back so it reads behind the ears */}
          <mesh position={[0, 0.9, -0.12]}>
            <cylinderGeometry args={[0.013, 0.013, 0.2, 8]} />
            <meshStandardMaterial color={agent.shade} roughness={0.7} />
          </mesh>
          <mesh ref={tip} position={[0, 1.03, -0.12]}>
            <sphereGeometry args={[0.062, 16, 16]} />
            <meshStandardMaterial
              color={agent.hueB}
              emissive={agent.hueB}
              emissiveIntensity={2.2}
              toneMapped={false}
            />
          </mesh>
        </group>
      </group>

      {/* Key fill in front, plus a rim behind in the bot's own bright hue.
          The rim is what lights the silhouette edges brighter than the
          interior — the trick that sells the translucent-jelly read. */}
      <pointLight
        position={[0, 0.9, 2.2]}
        distance={5}
        intensity={0.25}
        color={agent.hueA}
      />
      <pointLight
        position={[0, 1.1, -1.4]}
        distance={4}
        intensity={0.7}
        color={agent.hueB}
      />

      {/* DOM chrome rides along with the bot */}
      {bubbleText && !isOpen && (
        <Html center portal={portal} position={[0, 1.62, 0]} zIndexRange={[30, 10]}>
          <div className="lil3-bubble" role="status">
            {bubbleText}
          </div>
        </Html>
      )}

      {isOpen && (
        <Html center portal={portal} position={[0, 2.05, 0]} zIndexRange={[60, 30]}>
          <div className="lil3-popover">
            <div className="lil3-popover-bar">
              <span className="lil3-dot lil3-dot-r" />
              <span className="lil3-dot lil3-dot-y" />
              <span className="lil3-dot lil3-dot-g" />
              <span className="lil3-popover-title">
                {agent.name} · {agent.role}
              </span>
            </div>
            <div className="lil3-popover-body">
              <p className="lil3-line lil3-line-cmd">{agent.cmd}</p>
              {agent.lines.map((line, li) => (
                <p className="lil3-line" key={li}>
                  {line}
                </p>
              ))}
              {/* drei's <Html> mounts a separate React root, so it sits
                  outside the Router — a <Link> here throws. Real href for
                  middle-click and crawlers, handler for client-side nav. */}
              <a
                className="lil3-popover-link"
                href="/myspace"
                onClick={(e) => {
                  e.preventDefault();
                  onNavigate("/myspace");
                }}
              >
                meet all 9 live tools →
              </a>
            </div>
          </div>
        </Html>
      )}

    </group>
  );
}

// ---------------------------------------------------------------------------
// Camera rig — pins the scene's ground plane (y = 0) to the bottom edge of the
// canvas so the bots read as standing on whatever sits below the perch.
// Computed from the live frustum rather than hard-coded: R3F only applies the
// <Canvas camera> prop at mount, and the value has to survive resizes.
// ---------------------------------------------------------------------------
const GROUND_MARGIN = 0.1; // world units of floor left visible below the feet
const VIEW_HEIGHT = 2.38; // world units visible top-to-bottom
// The perch is ~4.7:1, so a normal fov would give a ~110deg *horizontal* field
// and a bot out at TRACK would sit ~47deg off-axis, where rectilinear
// projection stretches it by 1/cos(47deg) — visibly fatter at the ends of the
// walk than in the middle. Pulling the camera back and narrowing the fov to
// suit keeps the same framing with only ~3% edge-to-centre variation.
const CAM_DIST = 16;

function CameraRig() {
  const camera = useThree((s) => s.camera);
  const size = useThree((s) => s.size);

  useEffect(() => {
    camera.fov =
      2 * Math.atan(VIEW_HEIGHT / 2 / CAM_DIST) * (180 / Math.PI);
    camera.position.set(0, VIEW_HEIGHT / 2 - GROUND_MARGIN, CAM_DIST);
    // R3F points the default camera at the origin, which pitches it down and
    // breaks the flat-frustum maths above. Level it back out.
    camera.rotation.set(0, 0, 0);
    camera.near = 0.1;
    camera.far = 100;
    camera.updateProjectionMatrix();
    camera.updateMatrixWorld();
  }, [camera, size.width, size.height]);

  return null;
}

// ---------------------------------------------------------------------------
// Scene + perch
// ---------------------------------------------------------------------------
function LilAgents3D() {
  const perchRef = useRef(null);
  const [openId, setOpenId] = useState(null);
  const [bubble, setBubble] = useState(null);
  const [visible, setVisible] = useState(true);
  const frozen = prefersReducedMotion();
  const history = useHistory();
  const navigate = useCallback((to) => history.push(to), [history]);

  // One mutable record per bot, shared so each can see the other's position
  // and avoid planning a stop on top of it. Kept in a ref: these mutate every
  // frame and must never trigger a React render.
  const walkStates = useRef(
    AGENTS.map((_, i) => ({
      pos: i === 0 ? 0.3 : 0.7,
      facing: i === 0 ? 1 : -1,
      dir: i === 0 ? 1 : -1,
      walking: false,
      // Stagger the first departure so they don't set off in lockstep
      pauseUntil: 1.5 + i * 3.5,
      startedAt: 0,
      duration: 1,
      from: i === 0 ? 0.3 : 0.7,
      to: i === 0 ? 0.3 : 0.7,
      travelled: 0,
      gait: 0, // 0..1 stride amplitude, eased with ground speed
    }))
  ).current;

  // Only render frames while the perch is on screen
  useEffect(() => {
    const el = perchRef.current;
    if (!el || typeof IntersectionObserver === "undefined") return;
    const io = new IntersectionObserver(
      ([entry]) => setVisible(entry.isIntersecting),
      { rootMargin: "120px" }
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);

  // Alternate thought bubbles between the two bots, same cadence as the
  // original so the two variants feel like the same characters
  useEffect(() => {
    if (frozen) return;
    let i = 0;
    const tick = () => {
      const agent = AGENTS[i % AGENTS.length];
      const phrases = agent.phrases;
      setBubble({
        agentId: agent.id,
        text: phrases[Math.floor(Math.random() * phrases.length)],
      });
      i += 1;
      window.setTimeout(() => setBubble(null), 3200);
    };
    const id = window.setInterval(tick, 6500);
    const first = window.setTimeout(tick, 2200);
    return () => {
      window.clearInterval(id);
      window.clearTimeout(first);
    };
  }, [frozen]);

  const toggle = useCallback((id) => {
    setOpenId((cur) => (cur === id ? null : id));
  }, []);

  // Escape closes the terminal, matching the original's behaviour
  useEffect(() => {
    if (!openId) return;
    const onKey = (e) => {
      if (e.key === "Escape") setOpenId(null);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [openId]);

  return (
    <div className="pj-agents-perch-3d" ref={perchRef}>
      <Canvas
        dpr={[1, 2]}
        frameloop={visible && !frozen ? "always" : "demand"}
        camera={{ position: [0, 1.09, 16], fov: 8.5, near: 0.1, far: 100 }}
        gl={{ antialias: true, alpha: true }}
        onPointerMissed={() => setOpenId(null)}
      >
        <CameraRig />
        <ambientLight intensity={0.5} />
        {/* Key from the upper left, matching where the specular sweep sits */}
        <directionalLight position={[-3, 4, 4]} intensity={1.15} />
        {/* Cool back rim to separate the bots from the dark hero */}
        <directionalLight
          position={[2, 3, -4]}
          intensity={0.6}
          color="#bcd4ff"
        />
        {/* Bounce off the tiles below */}
        <directionalLight position={[0, -3, 2]} intensity={0.25} />

        {AGENTS.map((agent, i) => (
          <Bot
            key={agent.id}
            agent={agent}
            side={i === 0 ? -1 : 1}
            phase={i === 0 ? 0 : 0.5}
            frozen={frozen}
            isOpen={openId === agent.id}
            bubbleText={
              bubble && bubble.agentId === agent.id ? bubble.text : null
            }
            onSelect={toggle}
            portal={perchRef}
            onNavigate={navigate}
            walkState={walkStates[i]}
            peers={walkStates}
          />
        ))}

        <ContactShadows
          position={[0, 0.012, 0]}
          opacity={0.45}
          width={14}
          height={3}
          blur={2}
          far={2}
          resolution={512}
        />
      </Canvas>
    </div>
  );
}

export default LilAgents3D;
